import {properties,state,persist,toggleFavorite,decide,getProperty,money,filterProperties} from './data.js';
import {header,footer,icon,photo,button,card,toast,openModal,escapeHTML} from './ui.js';
import {home,search,favorites} from './public.js';
import {matchPage,matchList} from './match.js';
import {propertyPage} from './property.js';
import {adminPage,propertyTable,registrationStep,setRegistrationStep,draft} from './admin.js';
const app=document.querySelector('#app');
const modal=document.querySelector('#modal');
let currentSlide=0;
const slides=['cinematic','living2','bedroom','balcony'];
let galleryIndex=0;
const gallery=['living','living2','dining','bedroom','kitchen','balcony','facade'];
function render(){if(modal.open)modal.close();const [path,query='']=(location.hash.slice(1)||'/').split('?');const parts=path.split('/').filter(Boolean);currentSlide=0;document.title=`${parts[0]==='admin'?'Painel administrativo':parts[0]==='match'?'Seu próximo Match':parts[0]==='busca'?'Encontre seu imóvel':'Seu lugar na Zona Leste'} · Property Match`;app.innerHTML=parts[0]==='busca'?search(new URLSearchParams(query)):parts[0]==='match'?matchPage(parts[1]||'intro'):parts[0]==='favoritos'?favorites():parts[0]==='imovel'?propertyPage(parts[1]):parts[0]==='signature'?propertyPage(parts[1],true):parts[0]==='admin'?adminPage(parts[1]||'dashboard'):parts[0]==='design-system'?designSystem():home();window.scrollTo({top:0,behavior:"instant"});document.querySelector('main')?.setAttribute('tabindex','-1'); const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('scroll-visible');observer.unobserve(entry.target);}}),{threshold:.15}); document.querySelectorAll('.architecture-story,.editorial-banner').forEach(x=>{x.classList.add('scroll-reveal');observer.observe(x);});}
window.addEventListener('hashchange',render);
function schedule(id){const p=getProperty(id);const local=new Date();const min=`${local.getFullYear()}-${String(local.getMonth()+1).padStart(2,'0')}-${String(local.getDate()).padStart(2,'0')}`;openModal(`<span class="eyebrow">SEU PRÓXIMO ENCONTRO</span><h2>Vamos conhecer?</h2><div class="modal-property">${photo(p.photo)}<div><b>${p.name}</b><small>${p.region} · ${p.id}</small></div></div><p>Escolha um horário para simular uma visita. Nenhuma reserva real será realizada.</p><form id="schedule-form"><input name="id" type="hidden" value="${p.id}"><label>Data da visita<input type="date" name="date" min="${min}" value="${min}" required></label><label>Horário<select name="time"><option>09:00</option><option>10:30</option><option>14:00</option><option>15:30</option><option>17:00</option></select></label><button class="btn green full">Confirmar visita demonstrativa${icon('check')}</button></form>`);}
function showGallery(key){galleryIndex=Math.max(0,gallery.indexOf(key));modal.classList.add('gallery-dialog');openModal(`<span class="eyebrow">GALERIA ILUSTRATIVA / PROPERTY MATCH</span><h2>Espaços em perspectiva.</h2><div id="gallery-photo">${photo(key)}</div><div class="button-row"><button class="btn outline" data-gallery-step="-1">${icon('back')}Anterior</button><span id="gallery-count">${galleryIndex+1} / ${gallery.length}</span><button class="btn outline" data-gallery-step="1">Próxima${icon('arrow')}</button></div><p class="micro">Fotografias das referências fornecidas. Sem correspondência com um imóvel real.</p>`);}
modal.addEventListener('close',()=>modal.classList.remove('gallery-dialog'));
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return; if(el.classList.contains('skip')){e.preventDefault();document.querySelector('main')?.focus();return;}
 if(el.dataset.favorite){e.preventDefault();toggleFavorite(el.dataset.favorite);document.querySelectorAll(`[data-favorite="${el.dataset.favorite}"]`).forEach(b=>{b.classList.toggle('active',state.favorites.includes(el.dataset.favorite));b.setAttribute('aria-pressed',state.favorites.includes(el.dataset.favorite));if(b.querySelector('span'))b.querySelector('span').textContent=state.favorites.includes(el.dataset.favorite)?'Imóvel salvo':'Salvar imóvel';});toast(state.favorites.includes(el.dataset.favorite)?'Imóvel salvo nos seus favoritos.':'Imóvel removido dos favoritos.');if(location.hash==='#/favoritos')render();}
 if(el.dataset.schedule){schedule(el.dataset.schedule);}
 if(el.dataset.contact){openModal(`<span class="eyebrow">ATENDIMENTO DEMONSTRATIVO</span><h2>Seu interesse é o primeiro passo.</h2><p>Em uma operação real, este espaço conectaria você à equipe responsável pelo ${getProperty(el.dataset.contact).name}. Nesta demonstração, nenhuma mensagem é enviada.</p><button class="btn green full" data-schedule="${el.dataset.contact}">Simular agendamento${icon('calendar')}</button>`);}
 if(el.dataset.gallery)showGallery(el.dataset.gallery);
 if(el.dataset.galleryStep){galleryIndex=(galleryIndex+Number(el.dataset.galleryStep)+gallery.length)%gallery.length;document.querySelector('#gallery-photo').innerHTML=photo(gallery[galleryIndex]);document.querySelector('#gallery-count').textContent=`${galleryIndex+1} / ${gallery.length}`;}
 if(el.dataset.slide){currentSlide=(currentSlide+Number(el.dataset.slide)+slides.length)%slides.length;document.querySelector('.signature-photo').className=`photo photo-${slides[currentSlide]} signature-photo`;document.querySelector('#slide-count').textContent=`0${currentSlide+1} — 04`;document.querySelectorAll('.slide-bars i').forEach((x,i)=>x.classList.toggle('active',i===currentSlide));}
 if(el.dataset.decision){const id=el.dataset.id;document.querySelectorAll('[data-decision]').forEach(x=>x.disabled=true);document.querySelector('.swipe-card')?.classList.add('swipe-out');decide(id,el.dataset.decision==='like');await new Promise(r=>setTimeout(r,220));const y=window.scrollY;render();window.scrollTo({top:y,behavior:"instant"});toast(el.dataset.decision==='like'?'Gostou? Este imóvel está nos seus matches.':'Imóvel descartado. Você pode revê-lo nos seus matches.');}
 if(el.dataset.matchTab){document.querySelectorAll('[data-match-tab]').forEach(x=>x.classList.toggle('selected',x===el));document.querySelector('#match-list-items').innerHTML=matchList(el.dataset.matchTab);}
 if(el.dataset.view){document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===el));document.querySelector('.results-body').className=`results-body ${el.dataset.view==='split'?'':el.dataset.view+'-only'}`;}
 if(el.dataset.mapProperty){document.querySelectorAll('[data-map-property]').forEach(x=>x.classList.toggle('selected',x===el));document.querySelector('#map-preview').innerHTML=card(getProperty(el.dataset.mapProperty),true);}
 if('adminMode' in el.dataset){document.querySelectorAll('[data-admin-mode]').forEach(x=>x.classList.toggle('selected',x===el));document.querySelector('#admin-table').innerHTML=propertyTable(filterProperties(properties,{mode:el.dataset.adminMode}));}
 if('wizardBack' in el.dataset){Object.assign(draft,Object.fromEntries(new FormData(document.querySelector('#registration-form'))));setRegistrationStep(registrationStep-1);render();}
 if('cancelAppointment' in el.dataset){state.appointments.splice(Number(el.dataset.cancelAppointment),1);persist();render();toast('Visita demonstrativa cancelada.');}
 switch(el.dataset.action){case'menu':document.querySelector('.site-header').classList.toggle('menu-open');el.setAttribute('aria-expanded',document.querySelector('.site-header').classList.contains('menu-open'));break;case'close-modal':modal.close();break;case'reset-match':state.likes=[];state.rejected=[];persist();render();break;case'notifications':openModal(`<span class="eyebrow">CENTRAL DE AVISOS</span><h2>Seu dia em perspectiva.</h2><p>O Residencial Neo Carrão está em revisão. Confira as fotografias e a avaliação territorial antes de uma publicação real.</p>${button('Ver imóveis','#/admin/imoveis')}`);break;case'clear-data':openModal(`<span class="eyebrow">DADOS DESTA DEMONSTRAÇÃO</span><h2>Começar de novo?</h2><p>Isso remove os favoritos, as decisões do Match e as visitas simuladas deste navegador.</p><button class="btn dark full" data-action="confirm-clear">Limpar dados da demonstração${icon('check')}</button>`);break;case'confirm-clear':state.favorites=[];state.likes=[];state.rejected=[];state.appointments=[];persist();modal.close();render();toast('Dados da demonstração limpos.');break;case'export-report':{const csv='\ufeffCódigo;Nome;Bairro;Modalidade;Valor;Área;Dormitórios\r\n'+properties.map(p=>[p.id,p.name,p.region,p.mode,p.price,p.area,p.beds].join(';')).join('\r\n');download(csv,'property-match-catalogo-demonstrativo.csv','text/csv;charset=utf-8');toast('Relatório demonstrativo exportado.');break;}}
});
document.addEventListener('submit',e=>{const form=e.target;const data=Object.fromEntries(new FormData(form));e.preventDefault();switch(form.getAttribute('id')){case'home-search':location.hash='/busca?'+new URLSearchParams(data);break;case'filters':location.hash='/busca?'+new URLSearchParams(Object.entries(data).filter(([,v])=>v!==''));if(location.hash==='#/busca?'+new URLSearchParams(Object.entries(data).filter(([,v])=>v!=='')))render();break;case'match-preferences':state.preferences={...data,max:Number(data.max),beds:Number(data.beds),quiet:data.quiet==='on'};persist();location.hash='/match/cards';break;case'schedule-form':if(state.appointments.some(a=>a.date===data.date&&a.time===data.time)){toast('Já existe uma visita neste horário. Escolha outro horário.');return;}state.appointments.push(data);persist();openModal(`<span class="eyebrow">TUDO CERTO NA DEMONSTRAÇÃO</span><h2>Visita simulada!</h2><p>${getProperty(data.id).name}<br>${data.date.split('-').reverse().join('/')} às ${data.time}</p><p>Nenhuma reserva ou mensagem real foi enviada. Você pode consultar ou cancelar este registro na agenda.</p>${button('Ver agendamentos','#/admin/agendamentos','green','calendar')}`);break;case'admin-filter':document.querySelector('#admin-table').innerHTML=propertyTable(filterProperties(properties,data));break;case'registration-form':Object.assign(draft,data);if(registrationStep<7){setRegistrationStep(registrationStep+1);render();}else{openModal(`<span class="eyebrow">FLUXO DEMONSTRATIVO CONCLUÍDO</span><h2>Seu imóvel está pronto para revisão.</h2><p>${escapeHTML(draft.title)} · ${escapeHTML(draft.code)}</p><p>Você percorreu as oito etapas do cadastro. Nenhum anúncio foi publicado e nenhum dado foi enviado a um servidor.</p>${button('Voltar ao portfólio','#/admin/imoveis','green')}`); setRegistrationStep(0); for(const key of Object.keys(draft))delete draft[key]; Object.assign(draft,{title:'',code:'',region:'',type:'Apartamento',mode:'Alugar',model:'Essencial'});}break;}});
function download(data,name,type){const blob=new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function designSystem(){return `${header()}<main id="main" class="section design-system"><span class="eyebrow">PROPERTY MATCH / SISTEMA VISUAL 1.0</span><h1>Estrutura. Identidade. Lugar.</h1><p>Brutalismo arquitetônico, geometria Bauhaus e uma expressão brasileira contida. Um sistema que organiza a experiência sem competir com os espaços.</p><div class="swatches">${[['Concreto','#EDE5D9'],['Grafite','#252422'],['Amarelo','#E8B51E'],['Vermelho','#C73526'],['Verde','#14543C'],['Marfim','#F7F3EC']].map(([n,c])=>`<div><i style="background:${c}"></i><span><b>${n}</b><br>${c}</span></div>`).join('')}</div><div class="ds-grid"><section class="panel"><span class="eyebrow">TIPOGRAFIA / ARCHIVO</span><div class="type-samples"><h1>Seu lugar.</h1><h2>Novos começos.</h2><h3>Um olhar para a cidade.</h3><p>Texto funcional, ritmo confortável e dados legíveis.</p><span class="eyebrow">RÓTULOS EDITORIAIS</span></div></section><section class="panel"><span class="eyebrow">COMPONENTES / AÇÕES</span><h2>Clareza para navegar.</h2>${button('Ação principal','#/busca')}${button('Property Match','#/match','green','heart')}${button('Ação secundária','#/','outline')}<div class="button-row"><span class="status green">Publicado</span><span class="status warm">Em revisão</span><span class="status neutral">Não disponível</span></div><label style="margin-top:24px">Campo de formulário<input placeholder="Uma informação de cada vez"></label></section><section class="panel"><span class="eyebrow">GEOMETRIA / MARCA</span><h2>Formas com função.</h2><div class="geometry-samples"><div class="bauhaus-tile"><i></i><i></i><i></i><i></i></div>${icon('layers')}${icon('pin')}${icon('heart')}</div></section><section>${card(properties[0])}</section></div><div class="ds-rules"><article><span class="eyebrow">01 / GRID E ESPAÇO</span><h3>Ordem arquitetônica.</h3><p>Grid de 12 colunas, subdividido em 2, 3, 4 ou 6 colunas por componente. Espaçamento base de 8 px, margens de 20 a 72 px e raios de 7 a 28 px.</p></article><article><span class="eyebrow">02 / SUPERFÍCIES</span><h3>Materialidade contida.</h3><p>Neutros predominantes, granulação sutil e fotografia protagonista. Vidro reservado à busca, marcadores e controles sobre imagens.</p></article><article><span class="eyebrow">03 / MOVIMENTO</span><h3>Ritmo com propósito.</h3><p>Transições de 200 a 500 ms, feedback de seleção e movimento reduzido respeitado. Foco de teclado visível e controles sem depender de hover.</p></article></div></main>${footer()}`;}
render();
